{"path":"lib/app/profile/profile_page.dart","content":"import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

part 'theme_mode_selector_bs.dart';

class ProfilePage extends StatefulWidget {
  const ProfilePage({super.key});

  @override
  State<ProfilePage> createState() => _ProfilePageState();
}

class _ProfilePageState extends State<ProfilePage> with SingleTickerProviderStateMixin {
  static final _tween = Tween<Alignment>(begin: Alignment.centerLeft, end: Alignment.centerRight);

  late final ValueNotifier<AppThemeMode> _themeModeNotifier;

  StreamSubscription<AppThemeMode>? _themeModeSubscription;

  SettingsRepository get _settingsRepository => context.read<SettingsRepository>();

  @override
  void initState() {
    super.initState();
    _themeModeNotifier = ValueNotifier(_settingsRepository.readThemeMode());
    _listenToThemeStream();
    _initAnimation();
  }

  @override
  void dispose() {
    _themeModeNotifier.dispose();
    _themeModeSubscription?.cancel();
    _alignmentController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _alignmentController = AnimationController(
      duration: const Duration(seconds: 2),
      vsync: this,
    )..repeat(reverse: true);
    _alignmentAnimation = _tween.animate(_alignmentController);
  }

  @override
  Widget build(BuildContext context) {
    final ThemeFonts fonts = context.fonts;
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.profile)),
      body: Padding(
        padding: const EdgeInsets.symmetric(vertical: 20),
        child: Column(
          children: [
            ValueListenableBuilder(
              valueListenable: _themeModeNotifier,
              builder: (BuildContext context, AppThemeMode mode, Widget? child) {
                return ListTile(
                  contentPadding: EdgeInsets.only(left: 24),
                  leading: Icon(Icons.dark_mode),
                  title: child,
                  subtitle: Text(
                    mode.titleOf(loc),
                    style: fonts.regular12,
                  ),
                  onTap: () async {
                    final AppThemeMode? newMode = await ThemeModeSelectorBottomSheet.show(context, mode);
                    if (newMode == null) return;

                    context.read<SettingsRepository>().setThemeMode(newMode);
                  },
                );
              },
              child: Text(
                loc.theme,
                style: fonts.regular16,
              ),
            ),
            const Spacer(),
            AlignTransition(
              alignment: _alignmentAnimation,
              child: ElevatedButton(
                onPressed: () => context.read<SettingsRepository>().setToken(null),
                child: Text(
                  loc.logout,
                  style: fonts.regular14.copyWith(color: context.colors.red),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  void _listenToThemeStream() {
    _themeModeSubscription = _settingsRepository.themeModeStream.listen((mode) {
      final AppThemeMode effective = mode ?? AppThemeMode.system;
      if (_themeModeNotifier.value != effective) {
        _themeModeNotifier.value = effective;
      }
    });
  }
}
"}

